  ('A5100-01', '내부심사 년간 계획 및 실적', 'A-5100', '작성일·연도 3(3개년 헤더) + 공정심사 분기 12칸(개별) + 시스템심사 grid(17~34행 2행 블록 9 프로세스: 3개년×분기 4 = 12칸 + 피심사부서). 심사구분·CSR·프로세스명 기정의(경영관리~구매업무 P — 9개), 범례(○◐●)·하단 3번 구분(35행~)·결재는 시트 몫. IATF §9.2 3년 주기 전 프로세스 커버.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '9', NULL, 'templates/standard/A5100-01.xlsx'),
  ('A5100-02', '내부심사 실시 계획서', 'A-5100', '갑지 헤더(관리번호·심사구분·심사항목·피심사부서·심사팀장·심사 우선순위 설정) + 심사 점수표 grid 2종(시스템 심사 11행·공정 심사 7행 — 등급 문자 입력 열만, 우측 배점·소계 수식은 시트 몫). 심사일정(a6)은 앱 기록용 — 을지 일정표는 시트 수기(을지 헤더 = 갑지 미러 수식). IATF §9.2 내부심사.', '["팀장","사업부장","사장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '9', NULL, 'templates/standard/A5100-02.xlsx'),
