  ('A8101-01', '비상사태 발생시 대응 방안', 'A-8101', '열람형(참조 문서) — 비상사태 발생시 대응 방안: 674행 책자형 문서(목차·기본대응 절차·비상 연락체계·상황별 방안, 이미지 40장) 기정의. 기록 동선은 훈련결과 보고서(A8101-02)·평가표(A8101-03)로.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '총무팀', '6,8', NULL, NULL),
  ('A8101-02', '비상사태 대비 훈련결과 보고서', 'A-8101', '좌/우 2벌 중 ★좌측(빈 틀)만 매핑 — 제목·목적·목표·훈련형태(체크 표기)·실시일자·주관팀·장소·동원장비·참석인원·참관감독·상황전파·시나리오·주요 훈련내용·참석자 명단. 우측 = E-7 팬더믹 작성례(모범 예시 성격 — 보존). 사진·상세 양식은 시트 몫.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '총무팀', '6,8', NULL, 'templates/standard/A8101-02.xlsx'),
