  ('B1100-07', '품질문제 발생 신속 대응 계통도', 'B-1100', '열람형(참조 문서) — 품질문제 발생 신속 대응 계통도(도해 이미지) + 신속대응 조직 연락망. 작성 양식 아님 — 개정은 규정 개정 절차로.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '8', NULL, NULL),
  ('B1100-08', '부적합품 처리 기준(가로)', 'B-1100', '열람형(참조 문서) — 부적합품 처리 기준 도해(전면 이미지 — 가로/세로 2시트 동일 문서). 작성 양식 아님. 처리 기록은 B1100-13 부적합품 처리대장으로.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '품질보증팀', '8', NULL, NULL),
