  ('K1100-07', '기본공급 계약서', 'K-1100', '열람형(참조 문서) — 기본공급 계약서: 조문 전문(제1장~ 기본 합의·개별 약정·납품 등) 기정의 법률 문서. 체결은 서면·인감 동선.', '["담당","팀장","사업부장"]', NULL, NULL, NULL, NULL, '공통', 0, NULL, NULL, '구매팀', '8', NULL, NULL),
